import { cookies, headers } from 'next/headers'

function getPreferredLanguage(acceptLanguage: string | null) {
  if (!acceptLanguage) return 'Not specified'

  const preferred = acceptLanguage
    .split(',')
    .map((entry, index) => {
      const [language, ...parameters] = entry.trim().split(';')
      const qualityParameter = parameters.find((parameter) =>
        parameter.trim().startsWith('q='),
      )
      const quality = qualityParameter
        ? Number(qualityParameter.trim().slice(2))
        : 1

      return { language: language.trim(), quality, index }
    })
    .filter(({ language, quality }) => language && quality > 0 && quality <= 1)
    .sort((a, b) => b.quality - a.quality || a.index - b.index)[0]

  return preferred?.language ?? 'Not specified'
}

export default async function UserPreferences() {
  const cookieStore = await cookies()
  const requestHeaders = await headers()
  const theme = cookieStore.get('theme')?.value ?? 'light'
  const language = getPreferredLanguage(requestHeaders.get('accept-language'))

  return (
    <section aria-labelledby="preferences-heading">
      <h2 id="preferences-heading">Current preferences</h2>
      <p>Theme: {theme}</p>
      <p>Preferred language: {language}</p>
    </section>
  )
}

